style.css:
@-moz-document domain("roblox.com") {
/* 1. Sets the Caine Background Image */
  body, .home-container, .rbx-header, .content, .container-main, .section, .light-theme, .dark-theme, .gotham-theme {
      background: url("https://i.pinimg.com/1200x/9c/9b/0b/9c9b0b475fd35051992bc987d3afef61.jpg") no-repeat center center fixed !important;
      background-size: cover !important;
  }
  .section-content, .content-container, .rbx-left-col, .menu-vertical, .scroller, .container-header {
      background: rgba(15, 15, 15, 0.65) !important;
  }
  .text, p, h1, h2, h3, .text-name, .text-title, .rbx-left-col a {
      color: #9b72ff !important;
  }
}
